import {Cloud} from './cloud.js';
const icons={camera:'<rect x="3" y="6" width="18" height="14" rx="3"/><path d="m8 6 1-3h6l1 3"/><circle cx="12" cy="13" r="4"/>',book:'<path d="M4 3h6a3 3 0 0 1 3 3v15a4 4 0 0 0-4-3H4zM20 3h-4a3 3 0 0 0-3 3v15a4 4 0 0 1 4-3h3z"/>',image:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="1"/><path d="m3 17 6-6 5 5 3-3 4 4"/>',chart:'<path d="M4 3v18h17M8 15l4-5 4 2 5-7"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="16" cy="17" r="3"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M3 16v4a1 1 0 0 0 1 1h16a1 1 0 0 0 1-1v-4"/>',plus:'<path d="M12 5v14M5 12h14"/>',check:'<path d="m5 12 4 4 10-10"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M3 17v4h18v-4"/>',focus:'<path d="M8 3H3v5M16 3h5v5M3 16v5h5M21 16v5h-5"/><circle cx="12" cy="12" r="3"/>'};
const icon=(n,s=20)=>`<svg width="${s}" height="${s}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.camera}</svg>`;
const tabs=[['analyze','camera','分析照片'],['practice','book','我的练习'],['references','image','参考图库'],['growth','chart','成长记录']];
const cloud=new Cloud();
const s={view:'analyze',selected:null,sample:false,sampleData:null,records:[],assets:[],exercises:[],worker:null,urls:new Map(),busy:false,loading:false,error:'',draft:{file:null,url:null,category:'人像',device:'手机',intent:'',refFile:null,refUrl:null,refId:'',parent:null,exercise:null},submission:null,refFile:null,refNote:'',generation:0};
const $=q=>document.querySelector(q);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=v=>new Date(v).toLocaleDateString('zh-CN',{month:'short',day:'numeric'});
const asset=id=>s.assets.find(a=>a.id===id);
const photoUrl=id=>s.urls.get(id)?.url||'';
const record=id=>s.records.find(r=>r.id===id);
const online=()=>!!s.worker&&Date.now()-new Date(s.worker.last_seen).getTime()<90000;
function usableReview(r){return !!r&&typeof r.summary==='string'&&Array.isArray(r.strengths)&&r.strengths.every(x=>typeof x==='string')&&Array.isArray(r.issues)&&r.issues.every(p=>p&&typeof p.title==='string'&&p.exercise&&Array.isArray(p.exercise.steps))&&(!r.reference||(Array.isArray(r.reference.observations)&&typeof r.reference.try_next==='string'))&&(!r.comparison||(Array.isArray(r.comparison.improved)&&Array.isArray(r.comparison.unchanged)))&&Array.isArray(r.uncertainties)}
const validRecords=()=>s.records.filter(r=>r.status==='completed'&&r.accurate&&usableReview(r.result));
const statusText=r=>({pending:online()?'等待分析':'等待电脑分析',running:'电脑正在分析',completed:r.accurate?'点评已完成':'已标记不准确',failed:'分析未完成'}[r.status]);
const button=(text,action,cls='',extra='')=>`<button class="button ${cls}" data-action="${action}" ${extra}>${text}</button>`;
function toast(t){const el=$('#toast');el.textContent=t;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),5000)}
function header(title,desc,action=''){return `<div class="heading"><div><div class="eyebrow">PHOTO NOTEBOOK</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function empty(title,desc,action='',i='camera'){return `<div class="empty">${icon(i,36)}<h2>${title}</h2><p class="caption">${desc}</p>${action}</div>`}
function connectionNotice(){if(!cloud.configured||!cloud.loggedIn)return `<div class="notice"><span>${cloud.configured?'登录你的私人档案，再上传照片和保存练习。':'云端档案尚未连接。你可以先查看示例，再按引导完成连接。'}</span><button data-tab="settings">${cloud.configured?'去登录':'连接与设置'}</button></div>`;if(s.error)return `<div class="notice"><span>${esc(s.error)}</span><button data-action="refresh">重试连接</button></div>`;if(!online())return `<div class="notice"><span>电脑助手暂未连接。可以上传排队，历史点评仍可查看。</span><button data-tab="settings">查看连接</button></div>`;return ''}
function render(){
 const name=s.view==='settings'?'连接与设置':tabs.find(t=>t[0]===s.view)?.[2];
 const account=cloud.loggedIn?(cloud.user?.email||'私人档案'):'尚未登录';
 const beforeFocus=document.activeElement?.id;const selStart=document.activeElement?.selectionStart,selEnd=document.activeElement?.selectionEnd;
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><img src="assets/favicon.svg" alt=""><div>取景<small>PHOTO NOTEBOOK</small></div></div><nav class="nav" aria-label="主导航">${tabs.map(([id,i,l])=>`<button data-tab="${id}" class="${s.view===id?'active':''}" ${s.view===id?'aria-current="page"':''}>${icon(i)}${l}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="side-note">从看懂一张照片开始，<br>慢慢找到自己的视角。</div><button class="settings-button" data-tab="settings">${icon('settings')}连接与设置</button></div></aside><main class="main"><header class="topbar"><span class="breadcrumb">个人摄影教练 / ${name}</span><span class="mobile-brand"><img src="assets/favicon.svg" alt="">取景</span><div class="account"><span title="${esc(account)}">${esc(account)}</span><button class="button subtle" data-tab="settings" aria-label="连接与设置">${icon('settings')}</button><div class="avatar">我</div></div></header><div class="workspace">${s.view==='settings'?settingsPage():connectionNotice()+({analyze:analysisPage,practice:practicePage,references:referencesPage,growth:growthPage}[s.view]||analysisPage)()}</div></main></div>`;
 bind();
 if(beforeFocus&&document.getElementById(beforeFocus)){const target=document.getElementById(beforeFocus);target.focus({preventScroll:true});if(typeof selStart==='number'&&target.setSelectionRange&&target.type!=='email'&&target.type!=='number')try{target.setSelectionRange(selStart,selEnd)}catch{}}
}
function navigate(view){if(![...tabs.map(t=>t[0]),'settings'].includes(view))throw new Error('未知页面');s.view=view;s.sample=false;s.selected=null;render();window.scrollTo({top:0,behavior:'instant'});}
function blankReport(){return `<aside class="panel"><div class="panel-head"><h2>一份有用的点评</h2>${icon('focus')}</div><div class="blank-report"><div class="report-symbol"><span></span><span></span><span></span></div><h2>从问题到下一次拍摄</h2><p class="caption">每次只抓住 1～3 个重点，让建议真正能用在拍摄中。</p>${[['01','哪里需要调整','在照片上指出具体位置，解释它怎样影响画面。'],['02','下次可以怎么拍','给出机位、光线、取景或人物状态的具体做法。'],['03','做一次小练习','围绕一个问题拍一组照片，再看改变是否有效。']].map(([n,h,p])=>`<div class="report-step"><b>${n}</b><div><h3>${h}</h3><p class="caption">${p}</p></div></div>`).join('')}</div><button class="sample-link" data-action="sample"><img src="assets/sample.jpg" alt="秋日街头人像示例"><div><span class="badge orange">示例</span><strong>看看一张照片怎样被点评</strong><span class="caption">不会计入你的成长记录</span></div></button></aside>`}
function uploadBox(){return `<label class="upload" id="drop"><span class="upload-icon">${icon('upload',30)}</span><strong>把照片放到这里</strong><span class="caption">拖放或点击选择 · JPEG / PNG · 最大 20MB</span><span class="button">选择照片</span><input id="photo" type="file" accept="image/jpeg,image/png" ${s.submission?'disabled':''}></label>`}
function analysisPage(){
 if(s.sample)return samplePage();
 const selected=record(s.selected);if(selected)return detailPage(selected);
 const d=s.draft,locked=s.busy||!!s.submission,origin=record(d.parent);
 return header(d.parent?'看看这次练习的改变。':'看懂这张，下次拍得更好。',d.parent?'围绕同一个问题比较，看看哪些调整起了作用。':'留住优点，找到最值得练习的一个问题。',d.parent?button('取消重拍','cancel-reshoot'):'')+`<div class="split"><section class="panel"><div class="panel-head"><h2>${d.parent?'练习后的重拍':'你的照片'}</h2><span class="badge">01 / 拍摄诊断</span></div><div class="panel-body">${origin?`<div class="reference-preview" style="margin-bottom:18px"><img src="${esc(photoUrl(origin.photo_id))}" alt="练习原片"><div><strong>原片已关联</strong><p class="caption">${esc(asset(origin.photo_id)?.filename)} · ${esc(s.exercises.find(e=>e.id===d.exercise)?.title||'重拍比较')}</p></div></div>`:''}${d.url?`<div class="photo-preview"><img src="${esc(d.url)}" alt="待分析照片"></div><div class="photo-actions"><span class="caption">${esc(d.file?.name)}</span>${button('更换照片','change','',locked?'disabled':'')}</div>`:uploadBox()}<div class="fields"><div class="field-row"><div class="field"><label for="category">照片类型</label><select id="category" ${locked?'disabled':''}>${['人像','日常随拍','风景','建筑'].map(x=>`<option ${d.category===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="device">拍摄设备</label><select id="device" ${locked?'disabled':''}>${['手机','相机'].map(x=>`<option ${d.device===x?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="field"><label for="intent">你想表达什么？<span>可选</span></label><textarea id="intent" maxlength="2000" ${locked?'disabled':''} placeholder="例如：想拍出朋友在街头自然、放松的感觉。">${esc(d.intent)}</textarea></div><div class="field"><label for="reference-file">参考图<span>可选 · 学习你喜欢的拍法</span></label>${d.refUrl||d.refId?`<div class="reference-preview"><img src="${esc(d.refUrl||photoUrl(d.refId))}" alt="参考照片"><div><strong>${esc(d.refFile?.name||asset(d.refId)?.filename)}</strong><p class="caption">和你的照片一起分析</p></div>${button('移除','remove-ref','subtle',locked?'disabled':'')}</div>`:`<label class="upload compact"><span>${icon('image',24)}</span><span class="caption">选择一张想学习的照片</span><input id="reference-file" type="file" accept="image/jpeg,image/png" ${locked?'disabled':''}></label>`}${cloud.loggedIn&&s.assets.some(a=>a.kind==='reference')?`<select id="reference-id" aria-label="从参考图库选择" ${locked?'disabled':''}><option value="">从参考图库选择</option>${s.assets.filter(a=>a.kind==='reference').map(a=>`<option value="${a.id}" ${d.refId===a.id?'selected':''}>${esc(a.filename)}</option>`).join('')}</select>`:''}</div></div><div class="submit-row"><span class="caption">只在你的电脑上进行 AI 分析</span>${button(`${s.busy?'正在保存…':s.submission?'继续提交':icon('focus',18)+'开始分析'}`,'submit','primary',s.busy?'disabled':'')}</div>${s.submission&&!s.busy?`<p class="caption" style="margin-top:16px">提交尚未确认，点击“继续提交”会恢复同一个任务。${button('放弃这次提交','abandon','subtle')}</p>`:''}</div></section>${blankReport()}</div>${s.records.length?`<div class="section-label">最近的照片</div><section class="panel">${s.records.slice(0,5).map(historyItem).join('')}</section>`:''}`;
}
function historyItem(r){return `<button class="history-item" data-open="${r.id}"><img src="${esc(photoUrl(r.photo_id))}" alt="${esc(asset(r.photo_id)?.filename||'照片')}"><div><strong>${esc(asset(r.photo_id)?.filename||'照片')}</strong><span class="caption">${date(r.created_at)} · ${esc(r.category)}${r.parent_id?' · 重拍':''}</span></div><span class="badge ${r.status==='completed'&&r.accurate?'green':r.status==='failed'?'red':'orange'}">${statusText(r)}</span></button>`}
function boxMarkup(issues){return (issues||[]).map((p,i)=>{const b=p.bbox;if(p.confidence==='low'||!Array.isArray(b)||b.length!==4||!b.every(Number.isFinite)||b.some(x=>x<0||x>1)||b[0]+b[2]>1.001||b[1]+b[3]>1.001)return '';return `<button class="annotation" data-highlight="${i}" aria-label="查看问题 ${i+1}：${esc(p.title)}" style="left:${b[0]*100}%;top:${b[1]*100}%;width:${b[2]*100}%;height:${b[3]*100}%"><span>${i+1}</span></button>`}).join('')}
function annotated(url,result){return `<div class="photo-preview"><div class="photo-wrap"><img src="${esc(url)}" alt="已点评照片">${boxMarkup(result?.issues)}</div></div>`}
function detailPage(r){
 const a=asset(r.photo_id),result=usableReview(r.result)?r.result:null;
 let right;if(r.status==='completed'&&result)right=reportMarkup(result,r);else if(r.status==='completed')right=empty('这份点评的格式不完整','照片仍可下载。请保留照片后删除此记录，再重新提交。');else right=`<aside class="panel"><div class="panel-head"><h2>${statusText(r)}</h2>${icon('clock')}</div><div class="blank-report"><h2>${r.status==='failed'?'这次还没完成点评。':'照片已经保存。'}</h2><p class="caption">${r.status==='failed'?esc(r.error||'请检查电脑助手后重试。'):r.status==='running'?'你的电脑正在查看照片。完成后，点评会自动出现在这里。':'打开 Mac 上的取景助手后，会自动分析这张照片。你可以离开这个页面。'}</p><div class="row" style="margin-top:22px">${r.status==='failed'||(r.status==='running'&&new Date(r.lease_until)<new Date())?button('重新分析','retry','primary',`data-id="${r.id}"`):''}${button('查看电脑连接','settings')}</div></div></aside>`;
 const parent=record(r.parent_id),ref=asset(r.reference_id);
 return header('这张照片的点评',`${date(r.created_at)} · ${esc(r.category)} · ${esc(r.device)}`,button('分析新照片','new'))+`<div class="split"><div><section class="panel"><div class="panel-head"><h2>${esc(a?.filename||'照片')}</h2><span class="badge">${statusText(r)}</span></div><div class="panel-body">${annotated(photoUrl(r.photo_id),result)}<div class="photo-actions"><span class="caption">标注为近似区域，点击数字查看对应建议</span>${button('下载照片','download-photo','',`data-id="${r.photo_id}"`)}</div>${r.intent?`<p class="caption">拍摄意图：${esc(r.intent)}</p>`:''}${r.duration_seconds?`<p class="caption">本地分析用时 ${Number(r.duration_seconds).toFixed(1)} 秒 · ${esc(r.model)}</p>`:''}${ref?`<div class="section-label">本次参考图</div><div class="reference-preview"><img src="${esc(photoUrl(ref.id))}" alt="参考图"><div>${esc(ref.filename)}<p class="caption">${esc(ref.note)}</p></div></div>`:''}${parent?`<div class="section-label">重拍前后</div><div class="comparison"><div><img src="${esc(photoUrl(parent.photo_id))}" alt="重拍前的原片"><label>原片</label></div><div><img src="${esc(photoUrl(r.photo_id))}" alt="练习后的重拍"><label>本次重拍</label></div></div>`:''}</div></section><div class="row" style="margin-top:16px">${r.status==='completed'?button('再拍一张来比较','reshoot','',`data-id="${r.id}"`):''}${button('删除这张记录','delete-record','danger',`data-id="${r.id}"`)}</div></div>${right}</div>`;
}
function reportMarkup(result,r=null){
 const sample=!r;
 return `<aside class="panel"><div class="panel-head"><h2>拍摄建议</h2><span class="badge ${sample?'orange':'green'}">${sample?'示例点评':'本地 AI'}</span></div><div class="strength"><h3>值得保留的地方</h3>${(result.strengths||[]).map(x=>`<p>${esc(x)}</p>`).join('')}</div><div class="panel-body"><p style="font-size:.95rem">${esc(result.summary)}</p></div>${r&&!r.accurate?'<div class="notice" style="margin:0 20px 20px">你已标记这份点评不准确，它不会计入成长趋势。</div>':''}${(result.issues||[]).map((p,i)=>`<article class="issue" id="issue-${i}"><div class="issue-title"><span class="number">${String(i+1).padStart(2,'0')}</span><h3>${esc(p.title)}</h3></div><div class="row"><span class="badge">${p.kind==='technical'?'技术观察':'审美建议'}</span><span class="badge">${esc(p.tag)}</span>${p.confidence==='low'?'<span class="badge orange">需要确认</span>':''}</div><dl>${[['在哪里',p.where],['为什么值得调整',p.why],['下次怎么拍',p.next_shot],['这张如何补救',p.salvage]].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>${p.parameter_advice?`<details><summary>展开拍摄参数建议</summary><p>${esc(p.parameter_advice)}</p></details>`:''}<div class="exercise-callout"><h3>${icon('book',16)} ${esc(p.exercise?.title)}</h3><ol>${(p.exercise?.steps||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ol><p class="caption">完成标准：${esc(p.exercise?.success_criteria)}</p>${button(sample?'连接后保存练习':s.exercises.some(e=>e.record_id===r.id&&e.issue_index===i)?'练习已保存':'加入我的练习',sample?'settings':'save-exercise','',`data-id="${r?.id||''}" data-index="${i}" ${r&&!r.accurate?'disabled':''}`)}</div></article>`).join('')}${!result.issues?.length?'<div class="panel-body"><p class="caption">这次没有明确需要优先改正的问题，可以继续尝试不同表达。</p></div>':''}${result.reference?`<article class="issue"><h3>向参考图学习</h3><dl><div><dt>可以观察到的拍法</dt><dd>${result.reference.observations.map(x=>`<p>${esc(x)}</p>`).join('')}</dd></div><div><dt>下一次试试</dt><dd>${esc(result.reference.try_next)}</dd></div><div><dt>两张照片的差异</dt><dd>${esc(result.reference.differences)}</dd></div></dl></article>`:''}${result.comparison?`<article class="issue"><h3>这次重拍的变化</h3><dl><div><dt>改善的地方</dt><dd>${result.comparison.improved.length?result.comparison.improved.map(x=>`<p>${esc(x)}</p>`).join(''):'目前没有足够证据确认改善。'}</dd></div><div><dt>还可以继续练习</dt><dd>${result.comparison.unchanged.map(x=>`<p>${esc(x)}</p>`).join('')||'继续保持本次做法。'}</dd></div><div><dt>下一步</dt><dd>${esc(result.comparison.next_step)}</dd></div></dl><p class="caption" style="margin-top:16px">${esc(result.comparison.limitations)}</p></article>`:''}${result.uncertainties?.length?`<div class="uncertainty"><strong>还不能确定</strong>${result.uncertainties.map(x=>`<p>${esc(x)}</p>`).join('')}</div>`:''}${r?`<div class="report-actions">${button(r.accurate?'这份点评不准确':'恢复计入成长记录','feedback','subtle',`data-id="${r.id}"`)}${button('导出这份点评','export-one','subtle',`data-id="${r.id}"`)}</div>`:''}</aside>`;
}
function samplePage(){if(!s.sampleData)return empty('正在打开示例','请稍等。');return header('一张照片，一次具体练习。',s.sampleData.source||'功能示例 · 人工编写 · 不计入你的成长记录',button('分析自己的照片','new'))+`<div class="split"><section class="panel"><div class="panel-head"><h2>秋日街头人像</h2><span class="badge orange">公开示例照片</span></div><div class="panel-body">${annotated('assets/sample.jpg',s.sampleData.result)}<p class="caption" style="margin-top:16px">示例照片：<a href="https://unsplash.com/photos/woman-on-street-LpZvsGynEho" target="_blank" rel="noopener">Wesley Tingey / Unsplash</a></p>${s.sampleData.duration_seconds?`<p class="caption">本机分析用时 ${s.sampleData.duration_seconds} 秒 · ${esc(s.sampleData.model)}</p>`:''}<p class="caption">示例只展示点评形式，你上传的照片会单独分析。</p></div></section>${reportMarkup(s.sampleData.result)}</div>`}
function practicePage(){return header('把建议，变成一次拍摄。','一次专注一个问题。拍完回来，看看改变。')+(s.exercises.length?`<div class="list">${s.exercises.map(e=>{const source=record(e.record_id),reshoots=s.records.filter(r=>r.exercise_id===e.id);return `<article class="exercise-card"><span class="badge ${e.state==='done'?'green':'orange'}">${({todo:'待练习',practicing:'练习中',done:'已完成'})[e.state]}</span>${!source?.accurate?'<span class="badge red">原点评已标记不准确</span>':''}<h3>${esc(e.title)}</h3><ol>${(e.steps||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ol><p>完成标准：${esc(e.success_criteria)}</p><div class="row">${button('查看原片点评','open','',`data-id="${e.record_id}"`)}${button('提交练习重拍','reshoot-exercise','primary',`data-id="${e.id}"`)}${e.state!=='done'&&reshoots.some(r=>r.status==='completed'&&r.accurate)?button('标记完成','finish-exercise','',`data-id="${e.id}"`):''}</div>${reshoots.length?`<div class="section-label">这项练习的重拍</div>${reshoots.map(historyItem).join('')}`:''}</article>`}).join('')}</div>`:empty('还没有练习任务','从照片点评中选择一个建议，加入你的练习清单。',button('去分析照片','new','primary'),'book'))}
function referencesPage(){const refs=s.assets.filter(a=>a.kind==='reference');return header('收集你想学习的拍法。','记录喜欢的光线、构图或人物状态，在下一次分析时一起比较。')+`<section class="panel" style="margin-bottom:26px"><div class="panel-body"><div class="field-row"><div class="field"><label for="library-file">添加参考照片</label><input id="library-file" type="file" accept="image/jpeg,image/png"><span class="caption">${s.refFile?esc(s.refFile.name):'JPEG / PNG · 最大 20MB'}</span></div><div class="field"><label for="reference-note">你喜欢它的什么？<span>可选</span></label><input id="reference-note" maxlength="1000" value="${esc(s.refNote)}" placeholder="例如：窗边柔和的光线"></div></div><div class="row" style="margin-top:20px">${button(s.busy?'正在保存…':'保存到参考图库','upload-reference','primary',s.busy?'disabled':'')}</div></div></section>`+(refs.length?`<div class="cards">${refs.map(a=>`<article class="record-card"><img src="${esc(photoUrl(a.id))}" alt="${esc(a.filename)}"><div class="card-body"><span class="badge">参考照片</span><h3>${esc(a.filename)}</h3><p>${esc(a.note||'还没有学习笔记')}</p><div class="row" style="margin-top:16px">${button('用于下一次分析','use-reference','',`data-id="${a.id}"`)}${button('删除','delete-reference','subtle',`data-id="${a.id}"`)}</div></div></article>`).join('')}</div>`:empty('留一张让你心动的照片','参考图库中的照片会保存在你的私人账号里。','','image'))}
function growthPage(){
 const valid=validRecords(),counts=new Map();
 for(const r of valid){const tags=new Set((r.result?.issues||[]).filter(i=>i.confidence!=='low').map(i=>i.tag));for(const tag of tags){const key=r.category+' / '+tag;counts.set(key,(counts.get(key)||0)+1)}}
 const trends=[...counts].filter(([,n])=>n>=3).sort((a,b)=>b[1]-a[1]);
 const comparisons=valid.filter(r=>r.parent_id&&r.result?.comparison&&record(r.parent_id)?.accurate);
 return header('看见进步，有照片为证。','回看你拍过的照片、反复出现的问题，以及练习带来的变化。',button('导出记录','export','',cloud.loggedIn?'':'disabled'))+`<div class="stats"><div class="stat"><span>已完成点评</span><strong>${s.records.filter(r=>r.status==='completed').length}</strong><p class="caption">其中 ${valid.length} 份计入趋势</p></div><div class="stat"><span>已完成练习</span><strong>${s.exercises.filter(e=>e.state==='done'&&record(e.record_id)?.accurate).length}</strong><p class="caption">以实际重拍记录为依据</p></div><div class="stat"><span>重拍对比</span><strong>${comparisons.length}</strong><p class="caption">记录改变，不用总分判断水平</p></div></div><div class="split"><section class="panel"><div class="panel-head"><h2>值得持续练习的问题</h2></div>${trends.length?trends.map(([tag,n])=>`<div class="trend"><strong>${esc(tag)}</strong><div class="bar"><span style="width:${Math.min(100,n/Math.max(valid.filter(r=>tag.startsWith(r.category+' / ')).length,1)*100)}%"></span></div><span class="caption">${n} 次点评中出现</span></div>`).join(''):`<div class="panel-body"><p class="caption">同类照片中至少出现 3 次的问题，才会显示在这里。还不能确定的建议和你标记不准确的点评不会计入。</p></div>`}</section><section class="panel"><div class="panel-head"><h2>练习带来的变化</h2></div>${comparisons.length?comparisons.slice(0,5).map(historyItem).join(''):`<div class="panel-body"><p class="caption">完成一次练习并提交重拍后，原片与重拍会一起保存在这里。没有明显改善时，也会如实记录。</p></div>`}</section></div><div class="section-label">照片与点评档案</div>${s.records.length?`<section class="panel">${s.records.map(historyItem).join('')}</section>`:empty('第一张照片，就是起点','你的照片、点评和练习记录会按时间保存在这里。',button('分析第一张照片','new','primary'),'chart')}`;
}
function settingsPage(){return header('让手机和电脑，连接同一份档案。','照片与点评云端保存，AI 分析留在你的 Mac。')+`<div class="settings-grid"><section class="panel"><div class="panel-head"><h2>1. 连接私人档案</h2><span class="badge ${cloud.configured?'green':''}">${cloud.configured?'已配置':'待配置'}</span></div><div class="panel-body"><form id="connection-form" class="fields" style="margin:0"><div class="field"><label for="project-url">Supabase 项目地址</label><input id="project-url" type="url" required value="${esc(cloud.config?.url||'')}" placeholder="https://你的项目.supabase.co" autocomplete="url"></div><div class="field"><label for="public-key">公开访问密钥</label><input id="public-key" required value="${esc(cloud.config?.key||'')}" placeholder="Publishable key / anon key" autocomplete="off"><span class="caption">只填写公开密钥，私密密钥不能用于网页。</span></div><button class="button primary" type="submit">保存连接</button></form><hr class="divider">${cloud.loggedIn?`<div><p>已登录：${esc(cloud.user?.email||'私人档案')}</p><div class="row" style="margin-top:16px">${button('测试云端连接','refresh')}${button('复制手机连接链接','copy-connection')}${button('退出登录','logout','subtle')}</div></div>`:`<form id="login-form" class="fields" style="margin:0"><div class="field"><label for="email">登录邮箱</label><input id="email" type="email" required autocomplete="email"></div><div class="field"><label for="password">密码</label><input id="password" type="password" required minlength="8" autocomplete="current-password"></div><div class="row"><button class="button dark" type="submit" ${s.busy?'disabled':''}>登录档案</button><button class="button" type="button" data-action="signup" ${s.busy?'disabled':''}>创建账号</button></div><span class="caption">第一次使用请创建账号，并按邮件完成邮箱验证。</span></form>`}${s.error?`<p class="error-text">${esc(s.error)}</p>`:''}</div></section><section class="panel"><div class="panel-head"><h2>2. 启动电脑助手</h2><span class="badge ${online()?'green':'orange'}">${online()?'已连接':'等待连接'}</span></div><div class="panel-body"><p class="caption">下载后解压，在 Mac 上打开“启动助手.command”。首次连接使用和网页相同的邮箱、密码。之后打开它，照片就会自动排队分析。</p><a class="button primary" href="downloads/photo-coach-assistant.zip" download>${icon('download',18)}下载 Mac 助手</a><p class="caption">第一次需要安装 Ollama 并下载图片模型。已安装的模型会重复使用，云端 AI 功能关闭。</p>${s.worker?`<p class="caption">上次连接：${new Date(s.worker.last_seen).toLocaleString('zh-CN')}<br>模型：${esc(s.worker.model)}</p>`:''}<hr class="divider"><h3>还没有云端项目？</h3><div class="setup-step"><span class="number">1</span><p>在 <a href="https://supabase.com/dashboard" target="_blank" rel="noopener">Supabase</a> 创建项目，选择适合你的区域。</p></div><div class="setup-step"><span class="number">2</span><div><p>打开项目的 SQL Editor，复制下面的建库脚本并运行一次。</p><div class="row" style="margin-top:10px">${button('复制建库脚本','copy-schema')}<a class="button" href="downloads/schema.sql" download>下载脚本</a></div></div></div><div class="setup-step"><span class="number">3</span><p>从项目的 Connect / API Keys 取得地址和公开密钥，填入左侧。将本站地址加入 Authentication → URL Configuration 的 Site URL 和 Redirect URLs，再创建账号。</p></div><a class="button" href="downloads/使用说明.html" target="_blank">打开详细使用说明</a></div></section></div>`}
async function validateFile(file){if(!file)throw new Error('请先选择照片。');if(!['image/jpeg','image/png'].includes(file.type))throw new Error('目前支持 JPEG、PNG。相机 RAW 或手机 HEIC 请先导出 JPEG。');if(file.size>20*1024*1024)throw new Error('照片超过 20MB，请先导出较小版本。');const bitmap=await createImageBitmap(file);const tooBig=bitmap.width*bitmap.height>50_000_000;bitmap.close();if(tooBig)throw new Error('照片超过 5000 万像素，请先导出较小版本。')}
async function chooseFile(file,reference=false){try{await validateFile(file);const d=s.draft;if(reference){if(d.refUrl)URL.revokeObjectURL(d.refUrl);d.refFile=file;d.refUrl=URL.createObjectURL(file);d.refId=''}else{if(d.url)URL.revokeObjectURL(d.url);d.file=file;d.url=URL.createObjectURL(file)}render()}catch(e){toast(e.message)}}
function resetDraft(){for(const u of [s.draft.url,s.draft.refUrl])if(u)URL.revokeObjectURL(u);s.draft={file:null,url:null,category:'人像',device:'手机',intent:'',refFile:null,refUrl:null,refId:'',parent:null,exercise:null};s.submission=null}
function needLogin(){if(!cloud.loggedIn){s.view='settings';render();toast('先连接并登录你的私人档案。');return false}return true}
let dataFlight=null;
function loadData(options={}){
 if(!cloud.loggedIn)return Promise.resolve();
 if(dataFlight?.generation===s.generation)return dataFlight.promise;
 const flight={generation:s.generation,promise:null};
 flight.promise=doLoadData(options).finally(()=>{if(dataFlight===flight)dataFlight=null});
 dataFlight=flight;return flight.promise;
}
async function doLoadData({quiet=false}={}){
 s.loading=true;const generation=s.generation;
 try{const [records,assets,exercises,worker]=await Promise.all([cloud.rows('records'),cloud.rows('photo_assets'),cloud.rows('exercises'),cloud.worker()]);if(generation!==s.generation)return;const previous=JSON.stringify([s.records,s.assets,s.exercises,online(),s.error]);s.records=records;s.assets=assets;s.exercises=exercises;s.worker=worker;s.error='';const newAssets=assets.filter(a=>!s.urls.has(a.id)||s.urls.get(a.id).expires<Date.now());await Promise.all(newAssets.map(async a=>{try{const url=await cloud.signed(a.path);if(generation===s.generation)s.urls.set(a.id,{url,expires:Date.now()+3300000})}catch{}}));if(s.selected&&!record(s.selected))s.selected=null;if(!quiet||previous!==JSON.stringify([s.records,s.assets,s.exercises,online(),s.error])||newAssets.length){if(s.view!=='settings'||!quiet)render()}}
 catch(e){if(generation!==s.generation)return;s.error=e.message;if(!quiet){render();toast(e.message)}}finally{s.loading=false}
}
async function submit(){if(s.busy)return;if(!s.draft.file){toast('先选择一张自己的照片。');return}if(!needLogin())return;s.busy=true;render();
 try{if(!s.submission)s.submission={id:crypto.randomUUID(),draft:{...s.draft},photo:null,reference:null};const sub=s.submission,d=sub.draft;if(!sub.photo)sub.photo=await cloud.upload(d.file);if(d.refFile&&!sub.reference)sub.reference=await cloud.upload(d.refFile,'reference');
 await cloud.rpc('create_analysis',{p_id:sub.id,p_photo:sub.photo.id,p_reference:sub.reference?.id||d.refId||null,p_category:d.category,p_device:d.device,p_intent:d.intent,p_parent:d.parent,p_exercise:d.exercise});
 if(d.exercise)try{await cloud.rpc('set_exercise_state',{p_id:d.exercise,p_state:'practicing'})}catch{}
 s.selected=sub.id;resetDraft();await loadData();toast(online()?'照片已保存，等待本地分析。':'照片已保存，电脑上线后会开始分析。');
 }catch(e){toast(e.message)}finally{s.busy=false;render()}}
async function abandon(){if(!s.submission)return;const sub=s.submission;try{await loadData();if(record(sub.id)){s.selected=sub.id;resetDraft();render();toast('这次提交已经保存，已打开记录。');return}for(const a of [sub.photo,sub.reference])if(a)await cloud.unused(a.id);resetDraft();render();toast('未完成提交已清理。')}catch(e){toast('清理尚未完成：'+e.message)}}
async function uploadReference(){if(s.busy||!needLogin())return;try{await validateFile(s.refFile);s.busy=true;render();await cloud.upload(s.refFile,'reference',s.refNote);s.refFile=null;s.refNote='';await loadData();toast('参考照片已保存。')}catch(e){toast(e.message)}finally{s.busy=false;render()}}
function startReshoot(id,exerciseId=null){const r=record(id);if(!r||r.status!=='completed')throw new Error('请先完成原片点评。');if(s.submission)throw new Error('请先完成或放弃当前提交。');resetDraft();s.draft.parent=id;s.draft.exercise=exerciseId;s.draft.category=r.category;s.draft.device=r.device;s.draft.intent=r.intent;s.draft.refId=r.reference_id||'';s.view='analyze';s.selected=null;s.sample=false;render();window.scrollTo({top:0,behavior:'instant'})}
function downloadData(name,data,mime='application/json'){const blob=data instanceof Blob?data:new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type:mime});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
async function confirmAction(title,description){const dialog=document.createElement('dialog');dialog.innerHTML=`<h2>${esc(title)}</h2><p>${esc(description)}</p><div class="row"><button class="button" data-cancel>取消</button><button class="button danger" data-confirm>确认删除</button></div>`;document.body.append(dialog);dialog.showModal();return new Promise(resolve=>{const finish=v=>{dialog.close();dialog.remove();resolve(v)};dialog.querySelector('[data-cancel]').onclick=()=>finish(false);dialog.querySelector('[data-confirm]').onclick=()=>finish(true);dialog.addEventListener('cancel',e=>{e.preventDefault();finish(false)})})}
async function runAction(action,target){
 const id=target?.dataset.id;
 switch(action){
 case 'settings':navigate('settings');break;
 case 'sample':s.sample=true;s.view='analyze';s.selected=null;if(!s.sampleData)s.sampleData=await fetch('assets/sample-review.json').then(r=>r.json());render();break;
 case 'new':s.view='analyze';s.sample=false;s.selected=null;render();break;
 case 'change':if(!s.submission){if(s.draft.url)URL.revokeObjectURL(s.draft.url);s.draft.file=null;s.draft.url=null;render()}break;
 case 'remove-ref':if(s.draft.refUrl)URL.revokeObjectURL(s.draft.refUrl);s.draft.refFile=null;s.draft.refUrl=null;s.draft.refId='';render();break;
 case 'cancel-reshoot':if(s.submission)throw new Error('请先完成或放弃当前提交。');resetDraft();render();break;
 case 'submit':await submit();break;
 case 'abandon':await abandon();break;
 case 'refresh':if(needLogin()){await loadData();if(!s.error)toast('云端档案已连接。');try{await cloud.cleanup()}catch{toast('有待清理的照片，将在连接恢复后继续清理。')}}break;
 case 'open':s.selected=id;s.view='analyze';s.sample=false;render();break;
 case 'reshoot':startReshoot(id);break;
 case 'reshoot-exercise':{const e=s.exercises.find(e=>e.id===id);startReshoot(e.record_id,id);break}
 case 'retry':if(await cloud.rpc('retry_job',{p_id:id})){await loadData();toast('已重新排队。')}else{await loadData();toast('任务状态已经变化。')}break;
 case 'save-exercise':if(needLogin()){await cloud.rpc('save_exercise',{p_record:id,p_index:Number(target.dataset.index)});await loadData();toast('已加入我的练习。')}break;
 case 'finish-exercise':await cloud.rpc('set_exercise_state',{p_id:id,p_state:'done'});await loadData();toast('练习已完成。');break;
 case 'feedback':await cloud.rpc('set_feedback',{p_id:id,p_accurate:!record(id).accurate});await loadData();toast(record(id).accurate?'已恢复计入成长记录。':'已标记不准确，并从成长趋势中排除。');break;
 case 'delete-record':if(await confirmAction('删除这张记录？','这张照片、点评、关联练习和后续重拍会一起删除。参考图库中的照片会保留。')){await cloud.rpc('delete_record',{p_id:id});s.selected=null;await loadData();try{await cloud.cleanup();toast('记录和照片已删除。')}catch{toast('记录已删除，图片清理将在连接恢复后继续。')}}break;
 case 'delete-reference':if(await confirmAction('删除参考照片？','仍关联点评的参考图，需要先删除对应点评。')){await cloud.rpc('delete_reference',{p_id:id});await loadData();try{await cloud.cleanup();toast('参考图已删除。')}catch{toast('参考图记录已删除，图片清理稍后继续。')}}break;
 case 'use-reference':if(s.submission)throw new Error('请先完成或放弃当前提交。');s.draft.refId=id;s.draft.refFile=null;if(s.draft.refUrl)URL.revokeObjectURL(s.draft.refUrl);s.draft.refUrl=null;s.view='analyze';s.selected=null;s.sample=false;render();toast('参考图已加入下一次分析。');break;
 case 'upload-reference':await uploadReference();break;
 case 'export':if(needLogin()){await loadData();if(s.error)throw new Error('连接恢复后才能导出完整记录。');downloadData('取景-摄影档案.json',{format:'photo-coach.v1',exported_at:new Date().toISOString(),records:s.records,assets:s.assets,exercises:s.exercises});toast('点评与练习已导出。原始图片请在照片页单独下载。')}break;
 case 'export-one':downloadData('取景-照片点评.json',{format:'photo-coach.v1',record:record(id),exercises:s.exercises.filter(e=>e.record_id===id)});break;
 case 'download-photo':{const a=asset(id);const url=await cloud.signed(a.path);const response=await fetch(url);if(!response.ok)throw new Error('图片下载失败');downloadData(a.filename,await response.blob(),'application/octet-stream');break}
 case 'logout':await cloud.logout();s.generation++;s.records=[];s.assets=[];s.exercises=[];s.worker=null;s.urls.clear();s.selected=null;resetDraft();s.error='';render();toast('已退出私人档案。');break;
 case 'signup':{if(!cloud.configured)throw new Error('请先保存云端连接。');const form=$('#login-form');if(!form.reportValidity())return;const email=$('#email').value,password=$('#password').value;s.busy=true;try{const loggedIn=await cloud.signup(email,password);if(loggedIn){await loadData();toast('账号已创建并登录。')}else toast('请查收验证邮件，验证邮箱后回来登录。')}finally{s.busy=false;render()}break}
 case 'copy-schema':await navigator.clipboard.writeText(await fetch('downloads/schema.sql').then(r=>r.text()));toast('建库脚本已复制，在新项目中运行一次。');break;
 case 'copy-connection':{const raw=JSON.stringify(cloud.config);const hash=btoa(unescape(encodeURIComponent(raw))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');await navigator.clipboard.writeText(location.origin+location.pathname+'#connect='+hash);toast('已复制连接链接，手机打开后登录同一账号。');break}
 }
}
function bind(){
 document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>navigate(b.dataset.tab));
 document.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{if(b.disabled||b.dataset.executing)return;b.dataset.executing='true';b.disabled=true;try{await runAction(b.dataset.action,b)}catch(e){toast(e.message)}finally{b.disabled=false;delete b.dataset.executing}});
 document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{s.view='analyze';s.sample=false;s.selected=b.dataset.open;render();window.scrollTo({top:0,behavior:'instant'})});
 document.querySelectorAll('[data-highlight]').forEach(b=>b.onclick=()=>{const issue=document.getElementById('issue-'+b.dataset.highlight);issue?.scrollIntoView({behavior:'smooth',block:'center'});issue?.classList.add('highlight');setTimeout(()=>issue?.classList.remove('highlight'),1800)});
 $('#photo')?.addEventListener('change',e=>chooseFile(e.target.files[0]));
 $('#reference-file')?.addEventListener('change',e=>chooseFile(e.target.files[0],true));
 const drop=$('#drop');if(drop){drop.addEventListener('dragover',e=>{e.preventDefault();drop.classList.add('drag')});drop.addEventListener('dragleave',()=>drop.classList.remove('drag'));drop.addEventListener('drop',e=>{e.preventDefault();if(!s.submission)chooseFile(e.dataTransfer.files[0])})}
 for(const key of ['category','device','intent'])document.getElementById(key)?.addEventListener('input',e=>s.draft[key]=e.target.value);
 $('#reference-id')?.addEventListener('change',e=>{s.draft.refId=e.target.value;s.draft.refFile=null;if(s.draft.refUrl)URL.revokeObjectURL(s.draft.refUrl);s.draft.refUrl=null;render()});
 $('#library-file')?.addEventListener('change',async e=>{try{await validateFile(e.target.files[0]);s.refFile=e.target.files[0];render()}catch(err){toast(err.message)}});
 $('#reference-note')?.addEventListener('input',e=>s.refNote=e.target.value);
 $('#connection-form')?.addEventListener('submit',async e=>{e.preventDefault();try{const url=$('#project-url').value.trim(),key=$('#public-key').value.trim();if(cloud.loggedIn&&(cloud.config.url!==url||cloud.config.key!==key))throw new Error('请先退出当前档案，再更换项目。');cloud.configure(url,key);s.generation++;s.records=[];s.assets=[];s.exercises=[];s.urls.clear();s.worker=null;s.error='';render();toast('连接已保存，请登录档案。')}catch(err){toast(err.message)}});
 $('#login-form')?.addEventListener('submit',async e=>{e.preventDefault();if(!cloud.configured){toast('请先保存云端连接。');return}const email=$('#email').value,password=$('#password').value;s.busy=true;try{await cloud.login(email,password);s.error='';await loadData();if(!s.error)toast('已登录私人档案。')}catch(err){s.error=err.message;toast(err.message)}finally{s.busy=false;render()}});
}
function registerWebMCP(){const ctx=document.modelContext;if(!ctx?.registerTool)return;const controller=new AbortController();const options={signal:controller.signal};const tools=[{name:'get_photo_coach_records',title:'查看摄影档案',description:'读取当前登录账号的照片任务状态与练习摘要，不包含照片、密钥或登录凭据。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async input=>{if(!input||Object.keys(input).length)throw new Error('不接受参数');if(!cloud.loggedIn)throw new Error('请先登录');await loadData();if(s.error)throw new Error(s.error);return {records:s.records.map(r=>({id:r.id,category:r.category,status:r.status,accurate:r.accurate})),exercises:s.exercises.map(e=>({id:e.id,title:e.title,state:e.state}))}}},{name:'navigate_photo_coach',title:'打开摄影教练页面',description:'切换到分析照片、我的练习、参考图库或成长记录，不提交照片、不创建任务。',inputSchema:{type:'object',properties:{view:{enum:['analyze','practice','references','growth']}},required:['view'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||Object.keys(input).length!==1||!tabs.some(t=>t[0]===input.view))throw new Error('页面参数无效');navigate(input.view);return {view:s.view}}}];for(const tool of tools)try{Promise.resolve(ctx.registerTool(tool,options)).catch(()=>{})}catch{}window.addEventListener('pagehide',()=>controller.abort(),{once:true})}
async function init(){
 const hash=new URLSearchParams(location.hash.slice(1));
 if(hash.has('connect')){try{const raw=hash.get('connect').replace(/-/g,'+').replace(/_/g,'/');const c=JSON.parse(decodeURIComponent(escape(atob(raw))));cloud.configure(c.url,c.key);s.view='settings';toast('云端连接已导入，请登录同一账号。')}catch{toast('连接链接无效。')}history.replaceState(null,'',location.pathname+location.search)}
 if(hash.has('access_token')&&cloud.configured){try{const token=hash.get('access_token');const user=await cloud.request('/auth/v1/user',{auth:false,headers:{Authorization:'Bearer '+token}});cloud.saveSession({access_token:token,refresh_token:hash.get('refresh_token'),expires_in:Number(hash.get('expires_in')||3600),user});toast('邮箱已验证。')}catch(e){toast(e.message)}history.replaceState(null,'',location.pathname+location.search)}
 render();registerWebMCP();if(cloud.loggedIn){await loadData();try{await cloud.cleanup()}catch{}}
 setInterval(()=>{if(cloud.loggedIn&&!s.busy&&!document.hidden)loadData({quiet:true})},10000);
 window.addEventListener('online',()=>loadData({quiet:true}));
}
init();
